#!/usr/bin/env bash
# PORT-NEW (docs/20 §3): deterministic synthetic inputs for the main-flow acceptance scenario S1.
# All media are generated by ffmpeg lavfi sources (no third-party footage → no licensing question).
#   tools/accept_fixtures.sh OUT_DIR
# Produces: clip_a.mp4 (1920x1080 30fps 4s, testsrc2 + 440 Hz aac), clip_b.mp4 (1080x1920 30fps 3s,
# mandelbrot, no audio), clip_c.mp4 (1280x720 25fps 3s, life + pink-noise aac), music.mp3 (6.5 s 330 Hz)
# and SHA256SUMS. Requires ffmpeg (any 7.x; box: 7.1.5).
set -euo pipefail
O="${1:?OUT_DIR}"; mkdir -p "$O"; cd "$O"
ff() { ffmpeg -hide_banner -loglevel error -y "$@"; }
ff -f lavfi -i testsrc2=size=1920x1080:rate=30:duration=4 -f lavfi -i sine=frequency=440:duration=4 -c:v libx264 -pix_fmt yuv420p -c:a aac -shortest clip_a.mp4
ff -f lavfi -i mandelbrot=size=1080x1920:rate=30 -t 3 -c:v libx264 -pix_fmt yuv420p clip_b.mp4
ff -f lavfi -i life=size=1280x720:rate=25:mold=10:ratio=0.1:seed=7 -f lavfi -i anoisesrc=d=3:c=pink:a=0.1:seed=7 -t 3 -c:v libx264 -pix_fmt yuv420p -c:a aac -shortest clip_c.mp4
ff -f lavfi -i sine=frequency=330:duration=6.5 -af volume=0.5 -c:a libmp3lame music.mp3
sha256sum clip_a.mp4 clip_b.mp4 clip_c.mp4 music.mp3 > SHA256SUMS
echo "fixtures in $O"
